        		AND EXISTS (SELECT 1 FROM edition_file def WHERE def.edition_id = de.id)
        		ORDER BY NOT EXISTS (SELECT 1 FROM edition_file dp JOIN media_file dpf ON dpf.id = dp.media_file_id
        			WHERE dp.edition_id = de.id AND dpf.missing_at IS NULL), de.tag IS NOT NULL, de.id LIMIT 1), cm.position IS NULL, COALESCE(cm.position, 0),
        		COALESCE(COALESCE((SELECT md.release_date FROM item_shown md WHERE md.item_id = item.id), CAST(item.parsed_year AS TEXT)), '~'), 0, 0, 0, 0, COALESCE((SELECT md.title FROM item_shown md WHERE md.item_id = item.id), item.parsed_title)
        	FROM e CROSS JOIN collection_movie cm ON cm.collection_id = e.collection_id CROSS JOIN item ON item.id = cm.item_id
        )\#u{20}
        		SELECT pe.playlist_id, ROW_NUMBER() OVER (PARTITION BY pe.playlist_id ORDER BY x.pos, x.entry_id, x.k1, x.k2, x.k3 COLLATE NOCASE, x.k4, x.k5, x.k6, x.k7, x.k8 COLLATE NOCASE, x.item_id) - 1 AS seq, x.entry_id,
        			x.item_id, COALESCE(x.edition_id, 0) AS edition_id, (SELECT COALESCE(re.runtime_ms, (SELECT f.duration_ms FROM edition_file rf JOIN media_file f ON f.id = rf.media_file_id
        	WHERE rf.edition_id = re.id ORDER BY f.size_bytes DESC, f.id LIMIT 1)) FROM edition re WHERE re.id = x.edition_id) AS runtime_ms
        		FROM x CROSS JOIN playlist_entry pe ON pe.id = x.entry_id WHERE (x.edition_id IS NULL OR EXISTS (SELECT 1 FROM edition_file vf WHERE vf.edition_id = x.edition_id))
        /* playlist_row(playlist_id,seq,entry_id,item_id,edition_id,runtime_ms) */;
        CREATE VIEW profile_station AS SELECT a.account_id, s.id AS station_id FROM profile_audience a CROSS JOIN station s
        	WHERE  (s.account_id = a.account_id OR s.visibility = 'server' OR s.visibility = 'household' AND s.household_id = (SELECT household_id FROM replica_meta)) AND (a.browse_mode = 0 OR
        		(SELECT (seen = total OR a.browse_mode = 2 AND seen > 0) FROM (SELECT COUNT(*) AS total, COALESCE(SUM((a.browse_mode = 0 OR a.browse_mode = 2 AND NOT EXISTS (SELECT 1 FROM item vr WHERE vr.id = COALESCE((SELECT vp.parent_id FROM item vp WHERE vp.id = item.parent_id), item.parent_id, item.id)
        		AND COALESCE(vr.kids_content, vr.kind = 'movie' AND (SELECT vm.content_rating FROM item_shown vm WHERE vm.item_id = vr.id) IN ('G')
        			OR vr.kind = 'show' AND (SELECT vm.content_rating FROM item_shown vm WHERE vm.item_id = vr.id) IN ('TV-Y','TV-Y7','TV-G')) = 1) OR a.browse_mode = 1 AND CASE (SELECT vl.kind FROM library vl WHERE vl.id = item.library_id)
        	WHEN 'music' THEN CASE item.kind WHEN 'song' THEN item.explicit = 0
        		WHEN 'album' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.parent_id = item.id AND vs.explicit = 0)
        		WHEN 'artist' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.explicit = 0 AND +vs.kind = 'song'
        			AND (vs.artist_id = item.id OR vs.parent_id IN (SELECT va.id FROM item va WHERE va.parent_id = item.id)))
        		ELSE 0 END
        	WHEN 'youtube' THEN CASE WHEN a.allow_list = 1
        		THEN EXISTS (SELECT 1 FROM account_allow vw WHERE vw.account_id = a.account_id AND vw.item_id = COALESCE((SELECT vp.parent_id FROM item vp WHERE vp.id = item.parent_id), item.parent_id, item.id))
        		ELSE EXISTS (SELECT 1 FROM item vc WHERE vc.id = COALESCE((SELECT vp.parent_id FROM item vp WHERE vp.id = item.parent_id), item.parent_id, item.id) AND vc.kids_content = 1) END
        	ELSE CASE WHEN a.allow_list = 1
        		THEN EXISTS (SELECT 1 FROM account_allow vw WHERE vw.account_id = a.account_id AND vw.item_id IN (item.id, item.parent_id,
        			(SELECT vp.parent_id FROM item vp WHERE vp.id = item.parent_id)))
        		ELSE EXISTS (SELECT 1 FROM item vr JOIN item_shown vm ON vm.item_id = vr.id WHERE vr.id = COALESCE((SELECT vp.parent_id FROM item vp WHERE vp.id = item.parent_id), item.parent_id, item.id)
        			AND instr(CASE vr.kind WHEN 'movie' THEN a.movie ELSE a.tv END, ',' || vm.content_rating || ',') > 0)
        	END END)), 0) AS seen
        			FROM playlist_row x CROSS JOIN item ON item.id = x.item_id WHERE x.playlist_id = s.playlist_id)))
        /* profile_station(account_id,station_id) */;
        CREATE VIEW music_artist AS SELECT a.id AS item_id, CASE a.kind WHEN 'song' THEN a.explicit = 0
        		WHEN 'album' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.parent_id = a.id AND vs.explicit = 0)
        		WHEN 'artist' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.explicit = 0 AND +vs.kind = 'song'
        			AND (vs.artist_id = a.id OR vs.parent_id IN (SELECT va.id FROM item va WHERE va.parent_id = a.id)))
        		ELSE 0 END AS clean,
        		(SELECT COUNT(*) FROM item al WHERE al.parent_id = a.id AND al.kind = 'album' AND (0 = 0 OR CASE al.kind WHEN 'song' THEN al.explicit = 0
        		WHEN 'album' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.parent_id = al.id AND vs.explicit = 0)
        		WHEN 'artist' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.explicit = 0 AND +vs.kind = 'song'
        			AND (vs.artist_id = al.id OR vs.parent_id IN (SELECT va.id FROM item va WHERE va.parent_id = al.id)))
        		ELSE 0 END)) AS album_count, ((SELECT COUNT(*) FROM item al JOIN item s ON s.parent_id = al.id WHERE al.parent_id = a.id AND +s.kind = 'song' AND (0 = 0 OR s.explicit = 0))
        		+ (SELECT COUNT(*) FROM item s JOIN item al ON al.id = s.parent_id
        			WHERE s.artist_id = a.id AND +s.kind = 'song' AND al.parent_id IS NOT a.id AND (0 = 0 OR s.explicit = 0))) AS song_count,
        		(SELECT COUNT(*) FROM item al WHERE al.parent_id = a.id AND al.kind = 'album' AND (1 = 0 OR CASE al.kind WHEN 'song' THEN al.explicit = 0
        		WHEN 'album' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.parent_id = al.id AND vs.explicit = 0)
        		WHEN 'artist' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.explicit = 0 AND +vs.kind = 'song'
        			AND (vs.artist_id = al.id OR vs.parent_id IN (SELECT va.id FROM item va WHERE va.parent_id = al.id)))
        		ELSE 0 END)) AS clean_album_count, ((SELECT COUNT(*) FROM item al JOIN item s ON s.parent_id = al.id WHERE al.parent_id = a.id AND +s.kind = 'song' AND (1 = 0 OR s.explicit = 0))
        		+ (SELECT COUNT(*) FROM item s JOIN item al ON al.id = s.parent_id
        			WHERE s.artist_id = a.id AND +s.kind = 'song' AND al.parent_id IS NOT a.id AND (1 = 0 OR s.explicit = 0))) AS clean_song_count
        	FROM item a WHERE a.kind = 'artist'
        /* music_artist(item_id,clean,album_count,song_count,clean_album_count,clean_song_count) */;
        CREATE VIEW music_album AS SELECT al.id AS item_id, ar.parsed_title AS artist_name, CASE al.kind WHEN 'song' THEN al.explicit = 0
        		WHEN 'album' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.parent_id = al.id AND vs.explicit = 0)
        		WHEN 'artist' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.explicit = 0 AND +vs.kind = 'song'
        			AND (vs.artist_id = al.id OR vs.parent_id IN (SELECT va.id FROM item va WHERE va.parent_id = al.id)))
        		ELSE 0 END AS clean,
        		(SELECT COUNT(*) FROM item s WHERE s.parent_id = al.id AND (0 = 0 OR s.explicit = 0)) AS song_count, (SELECT COALESCE(SUM(f.duration_ms), 0) FROM item s JOIN item_file x ON x.item_id = s.id JOIN media_file f ON f.id = x.media_file_id
        		WHERE s.parent_id = al.id AND (0 = 0 OR s.explicit = 0)) AS duration_ms,
        		(SELECT COUNT(*) FROM item s WHERE s.parent_id = al.id AND (1 = 0 OR s.explicit = 0)) AS clean_song_count, (SELECT COALESCE(SUM(f.duration_ms), 0) FROM item s JOIN item_file x ON x.item_id = s.id JOIN media_file f ON f.id = x.media_file_id
        		WHERE s.parent_id = al.id AND (1 = 0 OR s.explicit = 0)) AS clean_duration_ms,
        		(EXISTS (SELECT 1 FROM item s WHERE s.parent_id = al.id) AND NOT EXISTS (SELECT 1 FROM item s WHERE s.parent_id = al.id
        		AND NOT EXISTS (SELECT 1 FROM item_file x JOIN track t ON t.media_file_id = x.media_file_id
        			WHERE x.item_id = s.id AND t.kind = 'audio' AND (t.codec IN ('flac','alac','wavpack') OR substr(t.codec, 1, 4) = 'pcm_')))) AS lossless
        	FROM item al JOIN item ar ON ar.id = al.parent_id WHERE al.kind = 'album'
        /* music_album(item_id,artist_name,clean,song_count,duration_ms,clean_song_count,clean_duration_ms,lossless) */;
        CREATE VIEW music_song AS SELECT s.id AS item_id, al.parsed_title AS album_title, al.parent_id AS album_artist_id, COALESCE(s.artist_id, al.parent_id) AS performer_id,
        	COALESCE(pa.parsed_title, ar.parsed_title) AS artist_name,
        	(SELECT f.duration_ms FROM item_file x JOIN media_file f ON f.id = x.media_file_id WHERE x.item_id = s.id ORDER BY f.id LIMIT 1) AS duration_ms,
        	COALESCE(s.parsed_year, al.parsed_year) AS year,
        	(SELECT t.codec FROM item_file x JOIN track t ON t.media_file_id = x.media_file_id WHERE x.item_id = s.id AND t.kind = 'audio'
        		ORDER BY x.media_file_id, t.stream_index LIMIT 1) AS codec, (SELECT COUNT(*) > 0 AND COUNT(*) = COUNT(uf.missing_at) FROM item_file ux
        		JOIN media_file uf ON uf.id = ux.media_file_id WHERE ux.item_id = s.id) AS unavailable, CASE s.kind WHEN 'song' THEN s.explicit = 0
        		WHEN 'album' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.parent_id = s.id AND vs.explicit = 0)
        		WHEN 'artist' THEN EXISTS (SELECT 1 FROM item vs WHERE vs.explicit = 0 AND +vs.kind = 'song'
        			AND (vs.artist_id = s.id OR vs.parent_id IN (SELECT va.id FROM item va WHERE va.parent_id = s.id)))
        		ELSE 0 END AS clean
        	FROM item s JOIN item al ON al.id = s.parent_id JOIN item ar ON ar.id = al.parent_id LEFT JOIN item pa ON pa.id = s.artist_id WHERE s.kind = 'song'
        /* music_song(item_id,album_title,album_artist_id,performer_id,artist_name,duration_ms,year,codec,unavailable,clean) */;
